-- Platsbeskrivningar, omgång 3 (32 platser). Skrivna utifrån platsernas egna hemsidor.
-- Kort text högst 7 ord, lång 70–100 ord.
begin;
update public.places set short_description = 'Sushi, poke bowls och asiatiska rätter', description = 'Fuji Sushi startade i Simrishamn 2024 och serverar sushi, poke bowls och asiatiska varmrätter från Thailand och Vietnam, till exempel den vietnamesiska nudelsoppan pho. Kocken Orrys thailändska rätter har fått en plats på menyn. Lunchmenyn ändras varje dag, med allt från stekta risrätter och soppor till moderna tolkningar av asiatiska klassiker. Man kan välja något lätt och fräscht eller något mer mättande. Maten kan ätas på plats eller beställas online för avhämtning. Fuji Sushi ligger mitt i Simrishamn.' where id = 122; -- Fuji Sushi
update public.places set short_description = 'Vandrarhem och pub i Gröstorp', description = 'Bengtssons Loge i Gröstorp är ett vandrarhem med pub, på en gård som troligen är den äldsta i byn och byggdes på 1700-talet. Vandrarhemmet har rum med två till sex bäddar på två våningar, fullt utrustade kök för självhushåll, tv-rum, toaletter och duschar. Det finns ingen frukost, och lakan tar man med själv eller hyr. Parkering och wifi ingår. På gården finns två platser för husbilar. Härifrån kan man också boka laxtrolling på Östersjön med fiskeguide. Puben har bordsbokning per telefon.' where id = 123; -- Bengtssons Loge
update public.places set short_description = 'Matlagningskurser, catering och smaksafari', description = 'Österlen Kokkonst är ett litet matföretag på slätten som drivs av Maria Persson. Ambitionen är att vara ett genuint och personligt matställe, där gästerna får god mat, gott värdskap och en vacker miljö. Österlen Kokkonst håller matlagningskurser, erbjuder catering och ordnar smaksafari på Österlen. Matkultur är ett stort intresse, och historien ses som en viktig källa till kunskap om matens betydelse för vårt välbefinnande. Den som är intresserad hör av sig direkt till Maria via telefon eller mejl för att boka.' where id = 124; -- Österlen Kokkonst
update public.places set short_description = 'Libanesisk mat från grunden, foodtruck och catering', description = 'Libanesiska Köket blandar Libanon och Italien och lagar all mat från grunden, med citron, persilja, mynta, italiensk olivolja och vitlök. Här finns veganska rätter, fisk och kött, och det mesta är laktosfritt och glutenfritt. Glutenfritt bröd finns som alternativ till pitabröd. Råvarorna kommer så långt det går från lokala producenter. Libanesiska Köket har en foodtruck som står i Brösarp på vintern och i hamnen i Kivik på sommaren, och erbjuder även catering till fester och andra tillfällen.' where id = 127; -- Libanesiska Köket
update public.places set short_description = 'Bageri och café med co-work i Borrby', description = 'Gamla Bageriet har ett bageri och café i Borrby och ett i Örnahusen, som har säsongsöppet. Här finns sallader, veckans soppa, mackor, nybakat bröd, söta bakverk och kvalitetskaffe. Bageriet bakar med ekologiska produkter och lokala råvaror från små producenter, använder långa jästider och maler en del av mjölet själv. Det finns inga glutenfria alternativ. I Borrby finns också ett avskilt co-workrum med skärmar, konferensbord och snabbt internet, och den som arbetar där får rabatt på lunch och fika.' where id = 128; -- Gamla Bageriet
update public.places set short_description = 'Kaffestopp och butik i gammalt garage', description = 'Huset i Hannas är ett kaffestopp i byn Hannas, med fokus på kaffe av hög kvalitet. I en avslappnad miljö i ett gammalt garage serveras kaffe, fika och grillade mackor. Under sommaren finns flera sorters bryggkaffe, och ibland ordnas livemusik i garaget. I den gamla affären bredvid finns Österlendesign med inredning och design. Huset i Hannas drivs av Wanna och Mange och har öppet främst under sommaren, några dagar i veckan. Aktuella öppettider finns på deras Instagram och hemsida.' where id = 129; -- Huset i Hannas
update public.places set short_description = 'Bed and breakfast på skånegård nära Hammenhög', description = 'Rävåkra B&B ligger i hjärtat av Österlen, omgivet av öppna fält och slingrande grusvägar. Gården är en traditionell trelängad skånegård från tidigt 1900-tal som byggdes om till bed and breakfast 2001. Här finns åtta personligt inredda rum, och inredningen och rummens namn är inspirerade av naturen och livet på landet. Varje morgon serveras en hemlagad och generös frukost med nybakat bröd. Värdarna bjuder på hembakat fikabröd och tips om promenader. Rummen bokas via Booking.com.' where id = 130; -- Rävåkra B&B Österlen
update public.places set short_description = 'Livsstilsbutik och kaffestuga vid kusten', description = 'Hylkegården ligger vid kustvägen mellan Brantevik och Skillinge och har haft kaffestuga sedan 1975. Här serveras kaffe med hembakade kakor, räkmacka och matiga pajer, bakat från grunden, i allmogemiljö eller i trädgården med utsikt över havet. I det gamla stallet finns en livsstilsbutik med allt från trend och design till antikviteter och kuriosa, och en klädavdelning med kända märken. Gården byggdes på 1700-talet och har tillhört samma familj sedan 1917. Hylkegården samarbetar med konstnärer och antikhandlare.' where id = 131; -- Hylkegården på Österlen
update public.places set short_description = 'Konditori med tårtor och smörgåstårtor', description = 'Norrmans Conditori ligger på Storgatan i Gärsnäs och har öppet alla dagar i veckan, även på helger. Konditoriet gör tårtor och smörgåstårtor i många varianter, och på hemsidan kan man se alla varianter och göra en beställning. Här kan man också köpa bröd och kaffebröd och stanna till för en fika. Inför högtider som jul och påsk gäller särskilda öppettider, och dessa finns på hemsidan. Beställningar görs enklast på telefon, och det är bra att höra av sig i god tid.' where id = 134; -- Norrmans Conditori HB
update public.places set short_description = 'Glutenfritt café i gammal såg och kvarn', description = 'Café Sågmöllan nära Kivik öppnade 1939 och är ett av de äldsta caféerna på Österlen. Mellan 1874 och 1920 fanns här en kombination av mjölkvarn och sågverk. I caféet är alla bakverk, smörgåsar och våfflor naturligt glutenfria, och nästan allt är mjölkfritt, så att så många som möjligt ska kunna få en fikastund. Våfflorna görs på laktosfri mjölk, och det finns vegansk hallonpaj med vegansk vaniljsås. På hemsidan finns allergiinformation, och Café Sågmöllan har säsongsöppet.' where id = 135; -- Café Sågmöllan
update public.places set short_description = 'Café och hembageri i Brösarp', description = 'Café Smulan i Brösarp har funnits sedan 1950-talet och är en omtyckt mötesplats i byn. Caféet och hembageriet drivs av Anna Gartz tillsammans med erfaren personal. Här bakas det varje dag, och man kan äta frukostbuffé från måndag till lördag på förmiddagen. Café Smulan tar emot beställningar på tårtor och smörgåstårtor, som ska vara gjorda senast klockan elva dagen innan, och vissa produkter kräver två till tre dagars beställning. Caféet har öppet vardagar och lördagar och håller stängt på söndagar.' where id = 137; -- Café Smulan
update public.places set short_description = 'Chokladfabrik med fabriksbutik i Skåne-Tranås', description = 'Österlenchoklad är en chokladfabrik i Skåne-Tranås som tillverkar all sin choklad från kakaobönor. I fabriksbutiken säljs choklad, praliner, tryfflar, bakverk och andra sötsaker. Pralinerna är handgjorda, och sortimentet blandar smaker efter säsong med en fast kollektion. Chokladboxar och presentaskar kan också beställas online och skickas i hela Sverige, och inför jul finns en adventskalender. Österlenchoklad passar bra för den som vill köpa med sig något gott hem från Österlen eller ge bort en present.' where id = 138; -- Österlenchoklad
update public.places set short_description = 'Litet personligt bageri i Tomelilla', description = 'Kringlan i Tomelilla är ett litet, personligt bageri med två anställda som drivs av Pia, som tog över 2017 och har omkring 20 års erfarenhet i yrket. Här finns ett brett utbud av bröd, bullar, bakelser, tårtor, smörgåstårtor och landgångar, och det mesta görs från grunden med smör. Man kan ta en fika, äta en lättlunch eller köpa med sig. Det finns gluten- och laktosfria alternativ, och mjölkproteinfritt kan beställas, men bageriet är inte glutenfritt. Beställningar görs via hemsidan.' where id = 139; -- Kringlan i Tomelilla
update public.places set short_description = 'Våffelcafé och catering på landet', description = 'Ebbas Café & Catering ligger på landet nära Kåseberga, och våfflor är husets stora passion. Här finns klassiska våfflor med grädde och sylt, nutellavåfflor, lyxvåfflor och matvåfflor, till exempel räkvåffla, klämmis och potatisvåffla. Det finns också hembakade kakor och glass. Caféet har öppet på söndagar, då det även säljs nybakade frallor på morgonen, och under hösten serveras lunch på tisdagar. Ebbas erbjuder catering med buffé, tårtor och bakverk, och lokalerna och trädgården kan hyras för bröllop och fester.' where id = 140; -- Ebba’s Cafe
update public.places set short_description = 'Hantverksbageri med beställning och upphämtning', description = 'Ravlunda Hantverksbageri arbetar lite annorlunda än de flesta bagerier. Man beställer sitt bröd i bageriets webbshop och hämtar det sedan på bestämda dagar, oftast fredagar och lördagar. I webbshoppen finns mer än bara bröd, och utbudet förnyas varje vecka. Bagaren har bakat det mesta, från småkakor till bröd, med inspiration från sin mormors bakning. Den som har en allergi kan fråga direkt via mejl. Aktuella upphämtningsdagar och nyheter finns på hemsidan och i sociala medier.' where id = 141; -- Ravlunda Hantverksbageri
update public.places set short_description = 'Växtbaserad gastronomi med hotell i Brösarp', description = 'Tastecelebration Residence i Brösarp är en restaurang med hotell, där Isabel Brummer lagar växtbaserad gastronomi. Hon bjuder in gästerna till ett kulinariskt äventyr inspirerat av det som växer nära, men också längre bort. Rätterna kombinerar tekniker från förr med dagens möjligheter och vänder sig till alla, från erfarna grönsaksälskare, veganer och vegetarianer till nyfikna allätare. Råvarorna väljs med stor kreativitet efter säsong. Den som vill äta kan boka bord direkt via deras hemsida, där även aktuell meny presenteras.' where id = 142; -- Tastecelebration Residence
update public.places set short_description = 'Gelato på gårdens mjölk och vedugnspizza', description = 'Olaols på Tobisborg är ett café och en restaurang nära Simrishamn med något för alla, från morfar och veganen till den sötsugna. Olaols är mest kända för sin gelato, som görs på dagsfärsk mjölk från grannen Rosdalas kor. Mjölken hämtas varje morgon och pastöriseras i det egna gårdsmejeriet, och sedan görs dagens gelato med lokala smaker. Här finns också matiga våfflor, smørrebrød, bullar och cookies. Restaurangen serverar vedugnspizza med italiensk och skånsk chark. Bord bokas via hemsidan.' where id = 143; -- Olaols Gelato
update public.places set short_description = 'Restaurang och café vid Sandhammarens strand', description = 'Sandhammarens Fyrgrill ligger ett stenkast från den vita sandstranden i Sandhammaren. Här finns en restaurang med à la carte, och på sommaren en större meny för både lunch och middag. Alla rätter går att beställa för avhämtning. I caféet serveras hembakade kakor, räkmacka, glass och drycker. Fyrgrillen erbjuder också catering till fester, bröllop, studenter och andra tillställningar, både för privatpersoner och företag. Öppettiderna varierar under året, så det är bra att kolla hemsidan inför ett besök.' where id = 144; -- Sandhammarens Fyrgrill
update public.places set short_description = 'Nostalgimuseum med över 100 bilar', description = 'Nostalgicafé the 50''s i Tryde, strax utanför Tomelilla, är ett 2400 kvadratmeter stort museum med över 100 bilar, däribland unika custombyggen. Museet är en tidsresa genom 1900-talets mest färgstarka epoker, där man vandrar genom autentiska miljöer från förr. Här kan man stå vid disken i en gammal lanthandel och titta in hos frisören och skomakaren. Museet har funnits i omkring 30 år och är en upplevelse för hela familjen. Det har öppet under sommaren, och här finns även ett café.' where id = 148; -- Tryde Nostalgimuseum
update public.places set short_description = 'Skulpturpark och konsthall nära Kivik', description = 'Kivik Art Centre är en skulpturpark och konsthall som startade 2006. Platsen arbetar i gränslandet mellan tredimensionell konst, arkitektur och natur, och verken förändras med landskapet och årstiderna. I skulpturparken finns verk av internationella och lokala konstnärer och arkitekter, och i konsthallen visas utställningar som byts ut. Initiativet kom från en grupp engagerade människor på Österlen som ville skapa en levande plats för konst och kultur. Kivik Art Centre ligger på Svabesholms Kungsgård och är en plats att återvända till.' where id = 149; -- Kivik Art Centre
update public.places set short_description = 'Världens största Hasse & Tage-museum', description = 'Hasse & Tage-museet i Tomelilla beskriver sig som världens minsta filmmuseum och världens största Hasse & Tage-museum. Här berättas om Hans Alfredson och Tage Danielsson, deras filmer, revyer och produktioner, och om tiden de verkade i. Museet drivs av en förening som man kan bli medlem i och även ge bort som present. Det har öppet på lördagar, och grupper kan boka besök på andra tider mot en avgift. Museet är ett roligt besök för alla som gillar svensk film och humor.' where id = 151; -- Hasse & Tage Museet
update public.places set short_description = 'Motormuseum med över 350 fordon', description = 'Autoseum i Simrishamn är ett motormuseum på över 6000 kvadratmeter med fler än 350 fordon. Museet beskriver sig som levande och i ständig förändring, eftersom nya fordon och utställningar byts in hela tiden. Här finns bland annat Saab-modeller, mopeder och miljöer som en kiosk från 70- och 80-talen och en scen från 1930-talet. Autoseum har säsongsöppet, främst från våren till hösten, så det är bra att kolla hemsidan innan besöket. Museet passar för både bilentusiaster och nyfikna familjer.' where id = 153; -- Autoseum
update public.places set short_description = 'Österlens äldsta museum, i Kivik', description = 'Kiviks Museum & Arkiv beskriver sig som Österlens äldsta museum och ligger på Bredarörsvägen i Kivik. Museet drivs av en stiftelse och samlar föremål, arkiv och bilder från bygden. Här finns ett barnens museum, ett café och en butik. Museet ordnar vandringar, föreläsningar, kurser och olika projekt om bland annat arkeologi och kulturarv i Kiviksbygden. Man kan bli stödmedlem eller volontär, och skänka föremål eller bilder till samlingarna. Öppettider och kommande program finns på museets hemsida.' where id = 155; -- Museum occh Arkiv på Kivik
update public.places set short_description = 'Slott och ekopark med vandringsleder', description = 'Christinehofs slott ligger i Christinehofs ekopark, ett natur- och kulturlandskap på omkring 1000 hektar mellan Brösarp och Andrarum. Slottet drivs av kulturföreningen Christinas Wänner. I ekoparken finns några av Skånes vackraste naturområden och viktiga kulturhistoriska platser, som Andrarums alunbruk, där de sista arbetarna lämnade bruket omkring 1925. Från slottets parkering utgår flera kortare promenader och vandringsleder, bland annat genom Borstakärrs våtmarker. Ekoparken är alltid öppen för besök, och på hemsidan finns kartor och mer information om de olika miljöerna.' where id = 157; -- Christinehofs Slott
update public.places set short_description = 'Engelsk trädgård med plantshop vid Svabesholm', description = 'Den Engelska Trädgården ligger vid Svabesholm nära Kivik och är en besöksträdgård i engelsk stil. Trädgården har säsongsöppet från våren till hösten, och då finns även en plantshop och en butik. Det kostar entré, men barn upp till 15 år går in gratis, och säsongskort ger rabatt på växter. Bara ledarhundar får följa med in i trädgården, men andra hundar kan vänta i entrén där det finns skugga och vatten. Grupper som vill ha guidning bokar i förväg via mejl.' where id = 164; -- Den Engelska Trädgården
update public.places set short_description = 'Ulf Lundells konstgalleri i Simrishamn', description = 'Rockhead Art är ett galleri på Fabriksgatan i Simrishamn där Ulf Lundell ställer ut sin konst. Galleriet öppnade 2015. Här finns hans måleri, grafiska blad och affischer, och ett urval av hans signerade böcker och skivor. Galleriet har säsongsöppet från maj till september, oftast några dagar i veckan, och säsongen avslutas med en finissage med rabatt på konsten. Ulf Lundell ställer ibland även ut på andra platser. Frågor om konsten kan mejlas till galleriet.' where id = 172; -- Rockhead Art
update public.places set short_description = 'Keramik och måleri i Sankt Olof', description = 'Ateljé Brännorna i Sankt Olof drivs av keramikern Thomas Alexanderson och konstnären Lena Viredius. Thomas arbetar gärna med drejning och gör både bruksgods och unika verk, ibland i stort format och som skulpturala objekt. Verken bränns i elugn eller vedugn, och en del är saltglaserade. Lena arbetar med måleri, mosaik och teckning. Under höst och vinter har ateljén inga fasta öppettider, men det går bra att ringa eller mejla för att komma förbi. Ateljén är med i Påskrundan och har en webbutik.' where id = 177; -- Ateljé Brännorna
update public.places set short_description = 'Keramikateljé på gård i Löderup', description = 'Gårdsateljén Österlen ligger på en gård från 1857 i Löderup, som Catharina och Peter har haft som hem sedan 2020. Här formger och tillverkar Catharina Elander Hemvik handgjord keramik med inspiration från naturen, trädgården och årstiderna, till exempel fat med handmålade taxar och kavlad keramik. Catharina håller också i det kreativa och leder kurser i ateljén, medan Peter står för värdskapet och det praktiska. Gården är en plats för keramik, skaparglädje och möten, och keramiken säljs på plats.' where id = 178; -- Gårdateljén Österlen
update public.places set short_description = 'Konstnärsdriven konsthall nära Simrishamn', description = 'Tjörnedala Konsthall drivs av Östra Skånes Konstnärsgrupp, ÖSKG, och är en konstnärsdriven plattform i östra Skåne. ÖSKG startade 1968, när ett tiotal konstnärer kring Maglehem och Degeberga började samarbeta för att bjuda in allmänheten till sina ateljéer. Det blev början på Konstrundan, Sveriges äldsta konstrunda, som öppnar varje långfredag. I konsthallen visas utställningar under året, och här finns pedagogisk verksamhet som ung konst, öppen ateljé och konstkroki på fredagar. Det kostar entré.' where id = 182; -- Tjörnedala Konsthall
update public.places set short_description = 'Konsthall med sommarutställningar i Bästekille', description = 'Fabriken Bästekille är en konsthall nära Kivik som beskriver sig som ett rum för fantasin. Här visas större utställningar under sommarsäsongen, ofta breda presentationer av en konstnärs hela verk, och utställningarna har uppmärksammats av bland andra Dagens Nyheter. Entréavgiften inkluderar ofta en utställningskatalog. Fabriken har säsongsöppet från försommaren till hösten, främst fredag till söndag. Vilken utställning som visas varierar från år till år, så det är bra att kolla hemsidan inför besöket.' where id = 184; -- Fabriken Bästekille
update public.places set short_description = 'Konsthall och konstbutik i Kivik', description = 'Kiviks Konsthall & Butik startades 2022 av Niklas och Petra i en stor och ljus lokal mitt i Kivik, som ofta kallas Österlens konstnärscentrum. Här visas utställningar med olika konstnärliga uttryck och tekniker, och man kan också köpa konst. Konsthallen samarbetar med grannen Ulriksdals trädgård och har deltagit i Skulptörförbundets jubileumsprogram. Målet är att vara ett självklart besöksmål för alla som är nyfikna på konst och kultur, med en familjär känsla. Utställningar och vernissager finns på hemsidan.' where id = 185; -- Kiviks Konsthall & Butik 
update public.places set short_description = 'Minimuseum och bysmedja i Gislöv', description = 'Gislövs Smidesmuseum ligger mitt i byn Gislöv och är ett litet museum med gamla anor. I bysmedjan finns en utställningslokal och aktiva smeder, och under sommaren kan man se dem smida på helgerna. I museet visas en ny temautställning varje år. I den långa längan finns sedan 2023 Studio Billa, med inredning, vintage och hantverksprodukter. Museet drivs med hjälp av utställningsvärdar, och den som vill hjälpa till kan höra av sig. Smidesmuseet är en liten kulturupplevelse mitt i ett vägkors på Österlen.' where id = 190; -- Gislövs Smidesmuseum
commit;
